//! The static abilities a merged permanent has from the cards under its top card
//! ([CR 702.140e]): "A mutated permanent has all abilities of each card and token that
//! represents it." Each is listed with the permanent's own, with the permanent's timestamp
//! ([CR 613.7a]): "A continuous effect generated by a static ability has the same timestamp
//! as the object the static ability is on". Its [`super::Apply::order`] is [`MERGED`] and its
//! index on its card's face, and its source is that card, so the order puts it after the
//! top card's abilities and before granted ones, as [`State::abilities`] lists them.
//!
//! [CR 702.140e]: https://yawgatog.com/resources/magic-rules/#R702140e
//! [CR 613.7a]: https://yawgatog.com/resources/magic-rules/#R6137a
//! [`State::abilities`]: crate::state::State::abilities

use beryl_kernel::derive::Rederive;

use crate::card::{Ability, FaceIx};
use crate::definition::Definition;
use crate::event::{Listens, Replaces};
use crate::fixed::Full;
use crate::layout::Layout;
use crate::state::{AbilityMask, Flag, State};
use crate::static_ability::Inputs;
use crate::table::{Capability, GameTable};

use super::{Apply, Applying, Listed, list_static};

/// The bit of [`super::Apply::order`] that marks a static ability of a card under a merged
/// permanent. A face has fewer than 64 abilities, so the index fits below it.
pub(super) const MERGED: u8 = 0x40;

/// Lists the static abilities with a continuous effect of the cards under the merged
/// permanent at battlefield position `i`, if it is one, and says whether it is one.
///
/// Out of line: only a game with a card that merges comes here, for a copy.
#[inline(never)]
pub(super) fn list<L: Layout>(
    s: &Rederive<'_, L>,
    t: &GameTable,
    list: &mut Option<Applying<L>>,
    i: usize,
) -> (bool, Result<(), Full>) {
    let slot = s.battlefield()[i];
    let mut listed = Ok(());
    let mut merged = false;
    for (card, face) in s.copiable(slot).merged_faces(t) {
        merged = true;
        for (ability, n) in t.def(card).face(face).abilities.iter().zip(0u8..) {
            let Some(spec) = ability.layer() else {
                continue;
            };
            debug_assert!(n < MERGED, "a face of fewer than 64 abilities");
            let on = Listed {
                at: i,
                order: MERGED | n,
                source: card,
                face,
            };
            listed = listed.and(list_static(s, list, on, ability, spec));
        }
    }
    (merged, listed)
}

/// The static ability `a` is a part of, of a card under the merged permanent in `slot`:
/// the ability at its index on the face of its source, the card, as the permanent has it.
pub(super) fn ability<L: Layout>(
    s: &Rederive<'_, L>,
    t: &GameTable,
    slot: L::Slot,
    a: &Apply<L>,
) -> &'static Ability {
    let face = s
        .copiable(slot)
        .merged_faces(t)
        .find_map(|(card, face)| (card == a.source).then_some(face))
        .unwrap_or(FaceIx::FRONT);
    &t.def(a.source).face(face).abilities[usize::from(a.order & !MERGED)]
}

/// Whether the merged permanent at battlefield position `at` still has the abilities of the
/// cards under it as an effect comes up: unless an effect so far removed all its abilities
/// ([`crate::state::State::keeps_merged`]).
pub(super) fn has_so_far<L: Layout>(s: &Rederive<'_, L>, at: usize) -> bool {
    let lost = s.rows()[at].lost;
    lost != L::AbilityMask::ALL
}

/// The faces of the cards under the merged permanent in `slot`, as definitions, if it is one:
/// only a copy effect makes a merged permanent's values ([`State::merge`]).
fn faces<'s, L: Layout>(
    s: &'s State<L>,
    t: &'s GameTable,
    slot: L::Slot,
) -> impl Iterator<Item = Definition<L>> + 's {
    let copy = s.object(slot).flags().has(Flag::Copy);
    copy.then(|| s.copiable(slot).merged_faces(t))
        .into_iter()
        .flatten()
        .map(|(card, face)| Definition::of_face(card, face))
}

/// `masks`, the kinds of event the permanents so far listen to and replace, with those of the
/// cards under the merged permanent in `slot` added, if it is one.
#[inline(never)]
pub(super) fn masks<L: Layout>(
    s: &State<L>,
    t: &GameTable,
    slot: L::Slot,
    masks: (Listens, Replaces),
) -> (Listens, Replaces) {
    faces(s, t, slot).fold(masks, |(l, r), what| {
        (l | what.may_listen(t), r | what.may_replace(t))
    })
}

/// `inputs`, what the static abilities so far read, with what those of the cards under the
/// merged permanent in `slot` read added, in a game with a card that merges.
pub(super) fn inputs<L: Layout>(
    s: &State<L>,
    t: &GameTable,
    slot: L::Slot,
    inputs: Inputs,
) -> Inputs {
    if !t.can(Capability::Merges) {
        return inputs;
    }
    faces(s, t, slot).fold(inputs, |inputs, what| inputs.union(what.layer_inputs(t)))
}
